import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../hooks/useAuth';
import {
  Box,
  Container,
  Typography,
  Paper,
  Grid,
  Chip,
  Alert,
  Button,
  IconButton,
  Tooltip,
  Badge,
  Card,
  CardContent,
  CardActions,
  Divider,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Avatar,
  CircularProgress,
  Fab
} from '@mui/material';
import {
  Warning as WarningIcon,
  Error as ErrorIcon,
  Info as InfoIcon,
  Notifications as BellIcon,
  Refresh as RefreshIcon,
  Settings as SettingsIcon,
  FilterList as FilterIcon,
  Close as CloseIcon,
  CheckCircle as CheckCircleIcon,
  Security as SecurityIcon,
  TrendingDown as TrendingDownIcon,
  Store as StoreIcon,
  Star as StarIcon,
  AttachMoney as AttachMoneyIcon
} from '@mui/icons-material';

const Alerts = () => {
  const [loading, setLoading] = useState(true);
  const [alerts, setAlerts] = useState([]);
  const [filteredAlerts, setFilteredAlerts] = useState([]);
  const [filters, setFilters] = useState({
    type: 'all',
    timeframe: '7days',
    onlyUnread: false,
    productName: '',
    sellerName: ''
  });
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  
  const { user } = useAuth();
  const navigate = useNavigate();
  
  useEffect(() => {
    // Verificar autenticação
    if (!user) {
      navigate('/auth/login');
      return;
    }
    
    // Carregar alertas
    const fetchAlerts = async () => {
      try {
        // Simulando dados para exemplo com foco em detecção de falsificação
        const mockAlerts = [
          {
            id: 1,
            type: 'fake_product',
            product: {
              id: 1,
              name: 'Cartucho HP 664XL Preto',
              pn: '3YM84AB',
              referencePrice: 199.90
            },
            currentPrice: 29.90,
            percentChange: -85,
            seller: 'Loja Suspeita',
            sellerRating: 2.1,
            riskLevel: 'CRÍTICO',
            createdAt: '2025-01-05T10:30:00',
            read: false,
            description: 'Preço 85% abaixo do valor de referência - POSSÍVEL FALSIFICAÇÃO'
          },
          {
            id: 2,
            type: 'fake_product',
            product: {
              id: 2,
              name: 'Cartucho HP 667 Colorido',
              pn: '3YM78AB',
              referencePrice: 179.90
            },
            currentPrice: 39.90,
            percentChange: -78,
            seller: 'TintasBaratas',
            sellerRating: 1.8,
            riskLevel: 'CRÍTICO',
            createdAt: '2025-01-05T09:15:00',
            read: false,
            description: 'Preço 78% abaixo do valor de referência - POSSÍVEL FALSIFICAÇÃO'
          },
          {
            id: 3,
            type: 'fake_product',
            product: {
              id: 3,
              name: 'Cartucho HP 667XL Preto',
              pn: '3YM81AB',
              referencePrice: 219.90
            },
            currentPrice: 45.90,
            percentChange: -79,
            seller: 'SuperOfertas',
            sellerRating: 2.3,
            riskLevel: 'CRÍTICO',
            createdAt: '2025-01-05T08:45:00',
            read: false,
            description: 'Preço 79% abaixo do valor de referência - POSSÍVEL FALSIFICAÇÃO'
          },
          {
            id: 4,
            type: 'price_drop',
            product: {
              id: 4,
              name: 'Garrafa de Tinta HP GT53 Preta',
              pn: '1VV22AL',
              referencePrice: 89.90
            },
            currentPrice: 35.90,
            percentChange: -60,
            seller: 'TintaMax',
            sellerRating: 3.2,
            riskLevel: 'ALTO',
            createdAt: '2025-01-05T07:20:00',
            read: false,
            description: 'Preço 60% abaixo do valor de referência - ATENÇÃO'
          },
          {
            id: 5,
            type: 'unauthorized_seller',
            product: {
              id: 5,
              name: 'Cartucho HP 667XL Colorido',
              pn: '3YM80AB',
              referencePrice: 199.90
            },
            currentPrice: 89.90,
            percentChange: -55,
            seller: 'Vendedor Não Autorizado',
            sellerRating: 1.5,
            riskLevel: 'CRÍTICO',
            createdAt: '2025-01-05T06:10:00',
            read: true,
            description: 'Vendedor não autorizado com preço suspeito'
          },
          {
            id: 6,
            type: 'price_drop',
            product: {
              id: 6,
              name: 'Cartucho HP 664 Colorido',
              pn: '3YM79AB',
              referencePrice: 149.90
            },
            currentPrice: 89.90,
            percentChange: -40,
            seller: 'Loja Confiável',
            sellerRating: 4.5,
            riskLevel: 'MÉDIO',
            createdAt: '2025-01-05T05:30:00',
            read: true,
            description: 'Preço 40% abaixo do valor de referência'
          }
        ];
        
        setAlerts(mockAlerts);
        setFilteredAlerts(mockAlerts);
        setLoading(false);
      } catch (error) {
        console.error('Erro ao carregar alertas:', error);
        setLoading(false);
      }
    };

    fetchAlerts();
  }, [user, navigate]);

  // Aplicar filtros
  useEffect(() => {
    let filtered = [...alerts];

    if (filters.type !== 'all') {
      filtered = filtered.filter(alert => alert.type === filters.type);
    }

    if (filters.onlyUnread) {
      filtered = filtered.filter(alert => !alert.read);
    }

    if (filters.productName) {
      filtered = filtered.filter(alert => 
        alert.product.name.toLowerCase().includes(filters.productName.toLowerCase())
      );
    }

    if (filters.sellerName) {
      filtered = filtered.filter(alert => 
        alert.seller.toLowerCase().includes(filters.sellerName.toLowerCase())
      );
    }

    setFilteredAlerts(filtered);
  }, [alerts, filters]);

  const handleMarkAsRead = (alertId) => {
    setAlerts(prev => prev.map(alert => 
      alert.id === alertId ? { ...alert, read: !alert.read } : alert
    ));
  };

  const handleDeleteAlert = (alertId) => {
    setAlerts(prev => prev.filter(alert => alert.id !== alertId));
  };

  const markAllAsRead = () => {
    setAlerts(prev => prev.map(alert => ({ ...alert, read: true })));
  };

  // Estatísticas dos alertas
  const criticalAlerts = filteredAlerts.filter(alert => alert.riskLevel === 'CRÍTICO').length;
  const highRiskAlerts = filteredAlerts.filter(alert => alert.riskLevel === 'ALTO').length;
  const fakeProductAlerts = filteredAlerts.filter(alert => alert.type === 'fake_product').length;
  const unreadAlerts = filteredAlerts.filter(alert => !alert.read).length;

  const getAlertIcon = (type) => {
    switch (type) {
      case 'fake_product':
        return <ErrorIcon color="error" />;
      case 'price_drop':
        return <TrendingDownIcon color="warning" />;
      case 'unauthorized_seller':
        return <SecurityIcon color="warning" />;
      default:
        return <InfoIcon color="info" />;
    }
  };

  const getRiskColor = (riskLevel) => {
    switch (riskLevel) {
      case 'CRÍTICO':
        return 'error';
      case 'ALTO':
        return 'warning';
      case 'MÉDIO':
        return 'info';
      default:
        return 'default';
    }
  };

  const formatTime = (dateString) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffInHours = Math.floor((now - date) / (1000 * 60 * 60));
    
    if (diffInHours < 1) return 'Agora mesmo';
    if (diffInHours < 24) return `${diffInHours}h atrás`;
    const diffInDays = Math.floor(diffInHours / 24);
    return `${diffInDays}d atrás`;
  };

  return (
    <Box sx={{ py: 3 }}>
      <Container maxWidth="xl">
        {/* Cabeçalho da Página */}
        <Box sx={{ mb: 4, display: 'flex', flexDirection: { xs: 'column', sm: 'row' }, justifyContent: 'space-between', alignItems: { xs: 'flex-start', sm: 'center' }, gap: 2 }}>
          <Box>
            <Typography variant="h4" component="h1" gutterBottom fontWeight="bold">
              🚨 Detecção de Falsificação
            </Typography>
            <Typography variant="body1" color="text.secondary">
              Sistema inteligente de alertas para produtos suspeitos
            </Typography>
          </Box>

          {/* Botões de Ação */}
          <Box sx={{ display: 'flex', gap: 2 }}>
            <Button
              variant="outlined"
              startIcon={<RefreshIcon />}
              onClick={() => window.location.reload()}
            >
              Atualizar
            </Button>
            <Button
              variant="outlined"
              startIcon={<SettingsIcon />}
              onClick={() => setShowSettingsModal(true)}
            >
              Configurações
            </Button>
          </Box>
        </Box>

        {/* Estatísticas dos Alertas */}
        <Grid container spacing={3} sx={{ mb: 4 }}>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'error.light', color: 'error.contrastText' }}>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                  <Avatar sx={{ bgcolor: 'error.main' }}>
                    <ErrorIcon />
                  </Avatar>
                  <Box>
                    <Typography variant="h4" fontWeight="bold">
                      {criticalAlerts}
                    </Typography>
                    <Typography variant="body2">
                      Críticos
                    </Typography>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'warning.light', color: 'warning.contrastText' }}>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                  <Avatar sx={{ bgcolor: 'warning.main' }}>
                    <WarningIcon />
                  </Avatar>
                  <Box>
                    <Typography variant="h4" fontWeight="bold">
                      {highRiskAlerts}
                    </Typography>
                    <Typography variant="body2">
                      Alto Risco
                    </Typography>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'info.light', color: 'info.contrastText' }}>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                  <Avatar sx={{ bgcolor: 'info.main' }}>
                    <SecurityIcon />
                  </Avatar>
                  <Box>
                    <Typography variant="h4" fontWeight="bold">
                      {fakeProductAlerts}
                    </Typography>
                    <Typography variant="body2">
                      Possível Falsificação
                    </Typography>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'primary.light', color: 'primary.contrastText' }}>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                  <Avatar sx={{ bgcolor: 'primary.main' }}>
                    <BellIcon />
                  </Avatar>
                  <Box>
                    <Typography variant="h4" fontWeight="bold">
                      {unreadAlerts}
                    </Typography>
                    <Typography variant="body2">
                      Não Lidos
                    </Typography>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        {/* Alertas */}
        {loading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
            <CircularProgress />
          </Box>
        ) : filteredAlerts.length === 0 ? (
          <Box sx={{ textAlign: 'center', py: 8 }}>
            <CheckCircleIcon sx={{ fontSize: 64, color: 'success.main', mb: 2 }} />
            <Typography variant="h6" color="text.secondary" gutterBottom>
              Nenhum alerta de falsificação detectado
            </Typography>
            <Typography variant="body2" color="text.secondary">
              O sistema está monitorando continuamente por produtos suspeitos
            </Typography>
          </Box>
        ) : (
          <Grid container spacing={3}>
            {filteredAlerts.map((alert) => (
              <Grid item xs={12} md={6} lg={4} key={alert.id}>
                <Card 
                  sx={{ 
                    height: '100%',
                    border: alert.riskLevel === 'CRÍTICO' ? '2px solid' : '1px solid',
                    borderColor: alert.riskLevel === 'CRÍTICO' ? 'error.main' : 'divider',
                    '&:hover': {
                      boxShadow: 6,
                      transform: 'translateY(-2px)',
                      transition: 'all 0.3s ease'
                    }
                  }}
                >
                  <CardContent>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
                      {getAlertIcon(alert.type)}
                      <Box sx={{ flexGrow: 1 }}>
                        <Typography variant="h6" fontWeight="bold">
                          {alert.product.name}
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                          PN: {alert.product.pn}
                        </Typography>
                      </Box>
                      <Chip
                        label={alert.riskLevel}
                        color={getRiskColor(alert.riskLevel)}
                        size="small"
                        variant="filled"
                      />
                    </Box>

                    <Alert severity={alert.riskLevel === 'CRÍTICO' ? 'error' : 'warning'} sx={{ mb: 2 }}>
                      {alert.description}
                    </Alert>

                    <List dense>
                      <ListItem>
                        <ListItemIcon>
                          <AttachMoneyIcon color="primary" />
                        </ListItemIcon>
                        <ListItemText
                          primary="Preço Atual"
                          secondary={`R$ ${alert.currentPrice.toFixed(2)}`}
                        />
                      </ListItem>
                      <ListItem>
                        <ListItemIcon>
                          <AttachMoneyIcon color="success" />
                        </ListItemIcon>
                        <ListItemText
                          primary="Preço de Referência"
                          secondary={`R$ ${alert.product.referencePrice.toFixed(2)}`}
                        />
                      </ListItem>
                      <ListItem>
                        <ListItemIcon>
                          <TrendingDownIcon color="error" />
                        </ListItemIcon>
                        <ListItemText
                          primary="Variação"
                          secondary={`${alert.percentChange}%`}
                        />
                      </ListItem>
                      <ListItem>
                        <ListItemIcon>
                          <StoreIcon color="info" />
                        </ListItemIcon>
                        <ListItemText
                          primary="Vendedor"
                          secondary={alert.seller}
                        />
                      </ListItem>
                      <ListItem>
                        <ListItemIcon>
                          <StarIcon color="warning" />
                        </ListItemIcon>
                        <ListItemText
                          primary="Avaliação"
                          secondary={`${alert.sellerRating}/5.0`}
                        />
                      </ListItem>
                    </List>

                    <Divider sx={{ my: 2 }} />

                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <Typography variant="caption" color="text.secondary">
                        {formatTime(alert.createdAt)}
                      </Typography>
                      {!alert.read && (
                        <Chip
                          label="Novo"
                          size="small"
                          color="primary"
                          variant="outlined"
                        />
                      )}
                    </Box>
                  </CardContent>

                  <CardActions sx={{ justifyContent: 'space-between', px: 2, pb: 2 }}>
                    <Button
                      size="small"
                      color="primary"
                      onClick={() => handleMarkAsRead(alert.id)}
                    >
                      {alert.read ? 'Marcar como não lido' : 'Marcar como lido'}
                    </Button>
                    <Button
                      size="small"
                      color="error"
                      onClick={() => handleDeleteAlert(alert.id)}
                    >
                      Excluir
                    </Button>
                  </CardActions>
                </Card>
              </Grid>
            ))}
          </Grid>
        )}
      </Container>
    </Box>
  );
};

export default Alerts;